import * as React from 'react'
import VisuallyHidden from '@radui/ui/VisuallyHidden'

import './loader.css'

export type LoaderProps = {
    variant?: 'dots' | 'bars' | 'orbit'
    /** Announced to screen readers. */
    label?: string
    /** Size in px. */
    size?: number
    color?: string
    className?: string
}

const PARTS = { dots: 3, bars: 4, orbit: 2 } as const

const Loader = ({ variant = 'dots', label = 'Loading', size = 32, color = 'currentColor', className }: LoaderProps) => (
    <span
        role="status"
        className={['rad-fx-loader', className].filter(Boolean).join(' ')}
        data-variant={variant}
        style={{ '--rad-fx-loader-size': `${size}px`, '--rad-fx-loader-color': color } as React.CSSProperties}
    >
        <VisuallyHidden asChild><span>{label}</span></VisuallyHidden>
        <span className="rad-fx-loader-art" aria-hidden="true">
            {Array.from({ length: PARTS[variant] }, (_, i) => (
                <span key={i} className="rad-fx-loader-part" style={{ '--rad-fx-loader-i': i } as React.CSSProperties} />
            ))}
        </span>
    </span>
)

export default Loader

.rad-fx-loader { display: inline-flex; }

.rad-fx-loader-art {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: calc(var(--rad-fx-loader-size, 32px) * 0.12);
    width: var(--rad-fx-loader-size, 32px);
    height: var(--rad-fx-loader-size, 32px);
}

.rad-fx-loader-part {
    background: var(--rad-fx-loader-color, currentColor);
    animation-delay: calc(var(--rad-fx-loader-i, 0) * 0.14s);
}

/* Dots: a bouncing trio. */
.rad-fx-loader[data-variant='dots'] .rad-fx-loader-part {
    width: 26%;
    aspect-ratio: 1;
    border-radius: 50%;
    animation: rad-fx-loader-bounce 0.9s ease-in-out infinite;
}

/* Bars: an equaliser. */
.rad-fx-loader[data-variant='bars'] .rad-fx-loader-part {
    width: 14%;
    height: 100%;
    border-radius: 3px;
    transform-origin: 50% 100%;
    animation: rad-fx-loader-eq 1s ease-in-out infinite;
}

/* Orbit: two dots circling a faint track. */
.rad-fx-loader[data-variant='orbit'] .rad-fx-loader-art { animation: rad-fx-loader-spin 1.1s linear infinite; }
.rad-fx-loader[data-variant='orbit'] .rad-fx-loader-art::before {
    content: '';
    position: absolute;
    inset: 13%;
    border: 2px solid var(--rad-fx-loader-color, currentColor);
    border-radius: 50%;
    opacity: 0.2;
}
.rad-fx-loader[data-variant='orbit'] .rad-fx-loader-part {
    position: absolute;
    width: 26%;
    aspect-ratio: 1;
    border-radius: 50%;
    top: 0;
    left: 37%;
}
.rad-fx-loader[data-variant='orbit'] .rad-fx-loader-part + .rad-fx-loader-part { top: auto; bottom: 0; opacity: 0.5; }

@keyframes rad-fx-loader-bounce {
    0%, 80%, 100% { transform: scale(0.6); opacity: 0.5; }
    40% { transform: scale(1); opacity: 1; }
}

@keyframes rad-fx-loader-eq {
    0%, 100% { transform: scaleY(0.35); }
    50% { transform: scaleY(1); }
}

@keyframes rad-fx-loader-spin {
    to { transform: rotate(360deg); }
}

/* Reduced motion: every variant becomes a slow opacity pulse, so "busy" still reads. */
@media (prefers-reduced-motion: reduce) {
    .rad-fx-loader-art,
    .rad-fx-loader .rad-fx-loader-part { animation: rad-fx-loader-pulse 2s ease-in-out infinite !important; transform: none !important; }
}

[data-rad-fx-motion='reduce'] .rad-fx-loader-art,
[data-rad-fx-motion='reduce'] .rad-fx-loader .rad-fx-loader-part { animation: rad-fx-loader-pulse 2s ease-in-out infinite !important; transform: none !important; }

@keyframes rad-fx-loader-pulse {
    0%, 100% { opacity: 0.4; }
    50% { opacity: 1; }
}
